def is_valid_ipv4(s: str) -> bool:
    if len(s) == 0 or s[0] == '.' or s[-1] == '.':
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True

